#!/usr/bin/env bash
# TPC-DS at scale factor 0.1, generated by DuckDB's bundled dsdgen and
# exported to one CSV per table.
#
# DuckDB's dsdgen is deterministic for a pinned binary: the same DuckDB at the
# same scale factor writes the same bytes. So what is pinned is the DuckDB
# version (by URL) and the output (by checksum); the output itself is never
# committed — see LICENSE-NOTE.md. CSVs are about 111 MB.
#
#	datasets/tpcds/fetch.sh
source "$(dirname "$0")/../lib.sh"

version=2.0.0
case "$(uname -m)" in
x86_64) arch=amd64 ;;
aarch64) arch=arm64 ;;
*) log "unsupported arch $(uname -m)"; exit 1 ;;
esac

bin=$DATA/tpcds/duckdb-$version
if [ ! -x "$bin" ]; then
	log "fetch   duckdb $version"
	mkdir -p "$(dirname "$bin")"
	curl -fSL --retry 3 -o "$bin.tgz" \
		"https://github.com/duckdb/duckdb/releases/download/v$version/duckdb-cli-linux-$arch.tar.gz"
	tar xzf "$bin.tgz" -C "$(dirname "$bin")"
	chmod +x "$(dirname "$bin")/duckdb"
	mv "$(dirname "$bin")/duckdb" "$bin"
	rm -f "$bin.tgz"
fi

out=$DATA/tpcds/sf0.1
if [ ! -f "$out/store_sales.csv" ]; then
	log "dsdgen  SF 0.1"
	mkdir -p "$out"
	rm -f "$DATA/tpcds/sf0.1.db"
	"$bin" -no-agent "$DATA/tpcds/sf0.1.db" "CALL dsdgen(sf=0.1);"
	"$bin" -no-agent "$DATA/tpcds/sf0.1.db" "EXPORT DATABASE '$out' (FORMAT CSV, HEADER true);"
	rm -f "$out/load.sql" "$out/schema.sql" "$DATA/tpcds/sf0.1.db"
fi

paths=()
for table in call_center catalog_page catalog_returns catalog_sales customer \
	customer_address customer_demographics date_dim household_demographics \
	income_band inventory item promotion reason ship_mode store \
	store_returns store_sales time_dim warehouse web_page web_returns \
	web_sales web_site; do
	paths+=("tpcds/sf0.1/$table.csv")
done
verify "${paths[@]}"
